import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Alert, Flex, Typography } from 'antd';

import ErrorIcon from 'assets/images/icons/error.svg?react';
import WarningIcon from 'assets/images/icons/warning.svg?react';
import { SourceStatusEnum } from 'entities/Channel';
import { ADD_BOT_LINK } from 'shared/consts';

interface IChannelStatusAlertProps {
	status?: SourceStatusEnum;
}

export const ChannelStatusAlert: FC<IChannelStatusAlertProps> = ({ status }) => {
	const { t } = useTranslation();

	return (
		<>
			{status === SourceStatusEnum.Restricted && (
				<Alert
					type="warning"
					description={
						<Flex align="center" justify="space-between" gap={8}>
							<Flex align="center" gap={8}>
								<WarningIcon style={{ minWidth: 16 }} />
								<Typography.Text>{t('Недостаточно прав боту для продолжения работы')}</Typography.Text>
							</Flex>
							<a href={ADD_BOT_LINK}>{t('Добавить')}</a>
						</Flex>
					}
				/>
			)}

			{status === SourceStatusEnum.NotAdmin && (
				<Alert
					type="warning"
					description={
						<Flex align="center" justify="space-between" gap={8}>
							<Flex align="center" gap={8}>
								<WarningIcon style={{ minWidth: 16 }} />
								<Typography.Text>{t('Для продолжения работы добавьте бота админом в канал')}</Typography.Text>
							</Flex>
							<a href={ADD_BOT_LINK}>{t('Добавить')}</a>
						</Flex>
					}
				/>
			)}

			{status === SourceStatusEnum.Rejected && (
				<Alert
					type="error"
					description={
						<Flex align="center" justify="space-between" gap={8}>
							<Flex align="center" gap={8}>
								<ErrorIcon style={{ minWidth: 16 }} />
								<Typography.Text>{t('Канал заблокирован')}</Typography.Text>
							</Flex>
							<a href="mailto:support@telerev.com">{t('В саппорт')}</a>
						</Flex>
					}
				/>
			)}
		</>
	);
};
